from .common import code, case

# Shared user-type contract required by the unchanged Day 3 exercises.
POLY='''Реализуйте Polynomial2(double a=0,double b=0,double c=0) для a*x*x+b*x+c. Индексы: p[0]=c, p[1]=b, p[2]=a. Две версии [] возвращают double& / const double&; неверный индекс → out_of_range. Поддержите +, -, унарные + и -, умножение на double с обеих сторон и const-operator()(double). Вывод в поток: [a,b,c] без пробелов. Сравнение == и != — точное по коэффициентам. Арифметика не изменяет операнды. Собственные приватные поля, без STL-контейнеров.'''
PCASES=[
case('Порядок коэффициентов','const Polynomial2 p(2,3,4); CHECK(p[0]==4 && p[1]==3 && p[2]==2);'),
case('Вычисление значения','const Polynomial2 p(2,3,4); CHECK(p(0)==4 && p(2)==18 && p(-1)==3);'),
case('Арифметика','const Polynomial2 p(2,3,4),q(1,2,3); CHECK((p+q)==Polynomial2(3,5,7)); CHECK((p-q)==Polynomial2(1,1,1)); CHECK(-p==Polynomial2(-2,-3,-4)); CHECK(+p==p);'),
case('Умножение','const Polynomial2 p(2,3,4); CHECK(2.0*p==Polynomial2(4,6,8)); CHECK(p*0==Polynomial2());'),
case('Индексирование','Polynomial2 p; p[2]=3; p[1]=2; p[0]=1; const auto& c=p; CHECK(c(2)==17); expect_throw<std::out_of_range>([&]{(void)c[3];}); expect_throw<std::out_of_range>([&]{(void)p[3];});','negative'),
case('Вывод и сравнение','std::ostringstream o; const Polynomial2 p(2,3,4); CHECK(&(o<<p)==&o); CHECK(o.str()=="[2,3,4]"); CHECK(p!=Polynomial2());'),
]


STRING='''Создайте CMyString на собственном динамическом массиве new char[], без std::string или готовых контейнеров в реализации хранения. Обязательны: пустой конструктор, explicit-конструктор из const char*, правило трёх, size() const -> std::size_t, c_str() const -> const char*, две версии [] (char& и const char&), ==, != по содержимому. nullptr в конструкторе → invalid_argument. Индексы [0,size()) доступны; остальные → out_of_range. Пустая строка имеет валидный c_str() с нулём. Копии независимы, самоприсваивание допустимо, присваивание возвращает CMyString&. При неудаче копирования исходное состояние сохраняется. Все размеры включают место для нуля; переполнение → length_error.'''
SCASES=[
case('Пустая строка','const CMyString s; CHECK(s.size()==0 && s.c_str()!=nullptr && s.c_str()[0]==0);','boundary'),
case('Буфер и ноль','char raw[]="hello"; const CMyString s(raw); raw[0]=char(88); CHECK(s.size()==5 && std::strcmp(s.c_str(),"hello")==0 && s.c_str()[s.size()]==0);'),
case('Глубокая копия','CMyString a("cat"); CMyString b(a); b[0]=char(98); CHECK(std::strcmp(a.c_str(),"cat")==0 && std::strcmp(b.c_str(),"bat")==0);'),
case('Присваивание и самоприсваивание','CMyString a("a"),b("bb"),c("ccc"); CHECK(&(a=b=c)==&a); b[0]=char(88); CHECK(std::strcmp(a.c_str(),"ccc")==0); a=a; CHECK(std::strcmp(a.c_str(),"ccc")==0);'),
case('Независимое время жизни','CMyString outside; {CMyString inside("alive"); outside=inside;} CHECK(std::strcmp(outside.c_str(),"alive")==0);'),
case('Неверные аргументы','expect_throw<std::invalid_argument>([]{CMyString s(nullptr);}); CMyString a("a"); const auto& b=a; expect_throw<std::out_of_range>([&]{(void)a[1];}); expect_throw<std::out_of_range>([&]{(void)b[9];});','negative'),
case('Сравнения','CHECK(CMyString("same")==CMyString("same")); CHECK(CMyString("a")!=CMyString("aa")); CHECK(CMyString()==CMyString(""));'),
case('Повторные циклы владения','for(int i=0;i<100;++i){CMyString a("resource"); CMyString b(a); CMyString c; c=b; CHECK(c==a);}','memory'),
case('Отказ выделения при присваивании','CMyString a("old"),b("replacement"); mastery_memory::fail_after=0; bool caught=false; try{a=b;}catch(const std::bad_alloc&){caught=true;} mastery_memory::fail_after=-1; if(caught){CHECK(std::strcmp(a.c_str(),"old")==0);}else{CHECK(std::strcmp(a.c_str(),"replacement")==0);}','exception'),
]
STYPE='static_assert(std::is_same_v<decltype(std::declval<CMyString&>()[0]),char&>); static_assert(std::is_same_v<decltype(std::declval<const CMyString&>()[0]),const char&>);'
OPS=''' Добавьте +, += для CMyString, унарный ! (обратная копия), operator^(int repeats) (повторение), потоковые << и >>. repeats<0 → invalid_argument, переполнение size()*repeats+1 → length_error. += поддерживает s+=s и возвращает ссылку. Ввод >> читает один токен, пропускает начальные пробелы; при ошибке объект неизменен. Пустые строки поддерживаются. Добавьте explicit operator const char*() const; в notes.md сравните явное и неявное преобразования и риски времени жизни.'''
OCASES=[
case('Конкатенация и алиасинг','CMyString s("xy"); CHECK(&(s+=s)==&s); CHECK(s==CMyString("xyxy")); CHECK((CMyString("a")+CMyString("b"))==CMyString("ab")); s+=CMyString(); CHECK(s==CMyString("xyxy"));'),
case('Обратный порядок','const CMyString s("abcd"); CHECK(!s==CMyString("dcba")); CHECK(s==CMyString("abcd")); CHECK(!CMyString()==CMyString());'),
case('Повторение','CHECK((CMyString("ab")^3)==CMyString("ababab")); CHECK((CMyString("ab")^0)==CMyString()); CHECK((CMyString()^5)==CMyString()); expect_throw<std::invalid_argument>([]{(void)(CMyString("a")^-1);});','boundary'),
case('Вывод и преобразование','const CMyString s("text"); std::ostringstream o; CHECK(&(o<<s)==&o); CHECK(o.str()=="text"); CHECK(std::strcmp(static_cast<const char*>(s),"text")==0);'),
case('Ввод и сохранение при ошибке','CMyString a("old"),b; std::istringstream in(" alpha beta"); in>>a>>b; CHECK(a==CMyString("alpha") && b==CMyString("beta")); std::istringstream empty(""); empty>>a; CHECK(empty.fail() && a==CMyString("alpha"));','negative'),
]
ERASE=''' Добавьте void erase(std::size_t position,std::size_t count). Допустим position<=size и count<=size-position, иначе out_of_range без изменения строки. count=0 допустим, в том числе erase(size(),0). Нельзя перевыделять память: адрес c_str() сохраняется. Сдвиг сохраняет завершающий ноль.'''
ECASES=[
case('Удаление середины без аллокации','CMyString s("abcdef"); const char* address=s.c_str(); mastery_memory::fail_after=0; s.erase(2,2); mastery_memory::fail_after=-1; CHECK(s==CMyString("abef") && s.c_str()==address);'),
case('Удаление конца и всей строки','CMyString s("abcdef"); s.erase(4,2); CHECK(s==CMyString("abcd")); s.erase(0,4); CHECK(s.size()==0 && s.c_str()[0]==0);','boundary'),
case('Нулевой диапазон','CMyString s("abc"); s.erase(3,0); CHECK(s==CMyString("abc")); CMyString e; e.erase(0,0); CHECK(e.size()==0);','boundary'),
case('Неверный диапазон','CMyString s("abc"); expect_throw<std::out_of_range>([&]{s.erase(2,2);}); expect_throw<std::out_of_range>([&]{s.erase(4,0);}); expect_throw<std::out_of_range>([&]{s.erase(1,std::numeric_limits<std::size_t>::max());}); CHECK(s==CMyString("abc"));','negative')]
REPLACE=''' Добавьте void replace_range(std::size_t position,std::size_t count,const char* replacement). Диапазон как в erase, nullptr → invalid_argument. Поддержите самоперекрытие, укорочение и удлинение, пустую вставку. Переполнение нового размера → length_error до выделения памяти. Сильная гарантия: при исключении исходная строка сохраняется. Контрольный пример: "ABCDE", replace_range(1,2,c_str()+3) → "ADEDE".'''
RCASES=[
case('Самоперекрытие','CMyString s("ABCDE"); s.replace_range(1,2,s.c_str()+3); CHECK(s==CMyString("ADEDE"));'),
case('Укорочение и удлинение','CMyString s("abcde"); s.replace_range(1,3,"X"); CHECK(s==CMyString("aXe")); s.replace_range(1,1,"12345"); CHECK(s==CMyString("a12345e"));'),
case('Полная замена и вставка в конец','CMyString s("abc"); s.replace_range(0,3,""); CHECK(s==CMyString()); s.replace_range(0,0,"xy"); s.replace_range(2,0,"z"); CHECK(s==CMyString("xyz"));','boundary'),
case('Ошибки не меняют объект','CMyString s("abc"); expect_throw<std::invalid_argument>([&]{s.replace_range(0,1,nullptr);}); expect_throw<std::out_of_range>([&]{s.replace_range(2,2,"x");}); CHECK(s==CMyString("abc"));','negative'),
case('Отказ выделения и откат','CMyString s("old"); mastery_memory::fail_after=0; bool caught=false; try{s.replace_range(0,1,"a much longer replacement");}catch(const std::bad_alloc&){caught=true;} mastery_memory::fail_after=-1; if(caught){CHECK(std::strcmp(s.c_str(),"old")==0);}else{CHECK(std::strcmp(s.c_str(),"a much longer replacementld")==0);}','exception'),
]
code(2,'C','A1 · C-string Lab','Реализуйте char* concat_copy(const char*,const char*) через strlen, strcpy, strcat; возвращаемый new[]-буфер принадлежит вызывающему. nullptr → invalid_argument. Реализуйте int compare_text(const char*,const char*) через strcmp (контракт знака), void copy_ints(int* dst,const int* src,size_t n) через memcpy (диапазоны не пересекаются), void shift_left(char* text,size_t count) через memmove. count<=strlen, иначе out_of_range; nullptr разрешён только в copy_ints при n=0. Проверяйте переполнение размеров до выделения/умножения.',[
case('Копирование и конкатенация','char* p=concat_copy("ab","cd"); CHECK(std::strcmp(p,"abcd")==0); delete[] p; p=concat_copy("",""); CHECK(p[0]==0); delete[] p;'),
case('Сравнение содержимого','CHECK(compare_text("az","ba")<0 && compare_text("a","a")==0 && compare_text("z","a")>0);'),
case('Массив int','int a[]={1,2,3},b[3]{}; copy_ints(b,a,3); CHECK(b[0]==1 && b[2]==3); copy_ints(nullptr,nullptr,0);'),
case('Перекрытие и пустая строка','char a[]="abcdef"; shift_left(a,2); CHECK(std::strcmp(a,"cdef")==0); shift_left(a,4); CHECK(a[0]==0); shift_left(a,0);','boundary'),
case('Некорректные аргументы','expect_throw<std::invalid_argument>([]{concat_copy(nullptr,"");}); expect_throw<std::invalid_argument>([]{compare_text("",nullptr);}); expect_throw<std::invalid_argument>([]{copy_ints(nullptr,nullptr,1);}); char a[]="a"; expect_throw<std::out_of_range>([&]{shift_left(a,2);}); CHECK(a[0]==char(97));','negative')],memory=True,tags=['C-строки','Dynamic memory'])
BADTEXT='#include <cstdlib>\n#include <cstring>\nclass BadText { char* data_; public: explicit BadText(const char* text){data_=static_cast<char*>(std::malloc(std::strlen(text)));std::strcpy(data_,text);} ~BadText(){delete[] data_;} };\n'
code(2,'C','A2 · BadText Repair','Исправьте данный BadText, самостоятельно определив дефекты. Добавьте правило трёх, c_str() const, char& operator[](size_t) с проверкой границ. nullptr → invalid_argument. Строка должна владеть независимым буфером. Объясните причины дефектов в notes.md. Исходный небезопасный код не запускается без ASan.',[
case('Независимость копий','BadText a("abc"); BadText b(a); b[0]=char(120); CHECK(std::strcmp(a.c_str(),"abc")==0);'),
case('Присваивание и время жизни','BadText a("old"); {BadText b("new"); CHECK(&(a=b)==&a);} a=a; CHECK(std::strcmp(a.c_str(),"new")==0);'),
case('Пустая строка','BadText a(""); CHECK(a.c_str()[0]==0); expect_throw<std::out_of_range>([&]{(void)a[0];});','boundary'),
case('Ошибки','expect_throw<std::invalid_argument>([]{BadText a(nullptr);}); BadText a("a"); expect_throw<std::out_of_range>([&]{(void)a[1];});','negative'),
case('Цикл владения','for(int i=0;i<100;++i){BadText a("longer text"); BadText b=a; CHECK(std::strcmp(b.c_str(),"longer text")==0);}','memory')],starter=BADTEXT,memory=True,unsafeStarter=True,tags=['Dynamic memory','Copy constructor'])
code(2,'C','A3 · CMyString Fundamentals',STRING,SCASES,checks=STYPE,memory=True,tags=['Dynamic memory','Copy constructor','Assignment operator'])
code(2,'C','B1 · CMyString Operators',STRING+OPS,SCASES+OCASES,checks=STYPE+' static_assert(!std::is_convertible_v<CMyString,const char*>);',memory=True,level='B',tags=['Dynamic memory','Перегрузка операторов'])
code(2,'C','B2 · Variadic Substring',STRING+''' Добавьте CMyString operator()(int count,...) const. count задаёт число следующих индексов, каждый передаётся как int. count<0 → invalid_argument, неверный индекс → out_of_range. count=0 → пустая строка. Число переданных аргументов должно соответствовать count (предусловие). Используйте cstdarg, не арифметику адреса count. Исходная строка неизменна.''',SCASES+[
case('Выборка face','const CMyString s("abcdef"); CHECK(s(4,5,0,2,4)==CMyString("face")); CHECK(s==CMyString("abcdef"));'),
case('Пустая и повторная выборки','const CMyString s("abc"); CHECK(s(0)==CMyString()); CHECK(s(3,1,1,1)==CMyString("bbb"));','boundary'),
case('Некорректные аргументы','const CMyString s("abc"); expect_throw<std::invalid_argument>([&]{s(-1);}); expect_throw<std::out_of_range>([&]{s(1,-1);}); expect_throw<std::out_of_range>([&]{s(2,0,3);});','negative')],memory=True,level='B',staticChecks=['no_vararg_pointer_trick'],tags=['Dynamic memory','Перегрузка операторов'])
code(2,'C','B3 · erase',STRING+ERASE,SCASES+ECASES,memory=True,level='B',tags=['C-строки','Exception safety'])
code(2,'C','B4 · replace_range',STRING+REPLACE,SCASES+RCASES,memory=True,level='B',tags=['Dynamic memory','Exception safety'])
code(2,'C','C · Resource Safety Challenge',STRING+OPS+ERASE+REPLACE+' Исправьте исходный частичный класс и доведите до полного контракта. В notes.md опишите инвариант и точки, где может возникнуть исключение. Не используйте STL-контейнеры для хранения.',SCASES+OCASES+ECASES+RCASES,starter=BADTEXT.replace('BadText','CMyString'),memory=True,unsafeStarter=True,level='C',minutes=80,tags=['Dynamic memory','Exception safety','Assignment operator'],staticChecks=['no_containers'])

MAXCASES=[case('int, double и char','CHECK(maximum(2,9)==9 && maximum(-3,-7)==-3); CHECK(maximum(2.5,2.75)==2.75); CHECK(maximum(char(97),char(122))==char(122));'),case('Равенство и явный тип','CHECK(maximum(7,7)==7); CHECK(maximum<double>(2.5,3)==3.0); CHECK(maximum(2.5,static_cast<double>(2))==2.5);','boundary'),case('Пользовательский тип только с <','struct Item{int v; bool operator<(const Item& r)const{return v<r.v;}}; CHECK(maximum(Item{2},Item{8}).v==8);','types')]
MINCASES=[case('Позиции минимума','CHECK(minimum_of_three(1,3,4)==1); CHECK(minimum_of_three(3,1,4)==1); CHECK(minimum_of_three(3,4,1)==1);'),case('Повторы и отрицательные','CHECK(minimum_of_three(-3,-3,1)==-3); CHECK(minimum_of_three(4,4,4)==4); CHECK(minimum_of_three(2.5,1.5,9.0)==1.5);','boundary'),case('Пользовательский тип','struct X{int n; bool operator<(const X& r)const{return n<r.n;}}; CHECK(minimum_of_three(X{2},X{1},X{3}).n==1);','types')]
IDXCASES=[case('Первый и последний минимум','int a[]={1,3,4},b[]={4,3,1}; CHECK(index_of_min(a,3)==0 && index_of_min(b,3)==2);'),case('Первый из равных','int a[]={3,1,1,2}; CHECK(index_of_min(a,4)==1); double b[]={2.5}; CHECK(index_of_min(b,1)==0);','boundary'),case('Недопустимые массивы','int a[]={1}; expect_throw<std::invalid_argument>([&]{index_of_min(a,0);}); expect_throw<std::invalid_argument>([]{index_of_min<int>(nullptr,1);});','negative'),case('Строковый тип','std::string a[]={"z","az","ba"}; CHECK(index_of_min(a,3)==1);','types')]
ACCESSCASES=[case('Обычные индексы','const int a[]={3,5,9}; CHECK(checked_access(a,3,0)==3 && checked_access(a,3,2)==9);'),case('Пустой и неверный индекс','const int a[]={3}; expect_throw<std::out_of_range>([&]{checked_access(a,0,0);}); expect_throw<std::out_of_range>([&]{checked_access(a,1,1);});','negative'),case('nullptr имеет приоритет','expect_throw<std::invalid_argument>([]{checked_access(nullptr,0,0);}); expect_throw<std::invalid_argument>([]{checked_access(nullptr,5,0);});','negative'),case('Очень большой индекс','int a[]={2}; expect_throw<std::out_of_range>([&]{checked_access(a,1,std::numeric_limits<std::size_t>::max());});','boundary')]
code(3,'C','A1 · checked_access','Напишите int checked_access(const int* array,std::size_t size,std::size_t index). Сначала проверяется nullptr → invalid_argument; затем index>=size → out_of_range. Верните значение элемента.',ACCESSCASES,tags=['Exception safety'])
code(3,'C','A2 · maximum<T>','Напишите шаблон T maximum(T a,T b), используя только < и копирование. При равенстве верните a. Тип не должен искусственно ограничиваться числами. В notes.md объясните maximum(2.5,3) и допустимые способы вызова с разными исходными типами.',MAXCASES,tags=['Template deduction'])
code(3,'C','A3 · swap_values<T>','Напишите шаблон void swap_values(T& a,T& b), обменивающий оригиналы копированием без std::swap. Поддержите самоперестановку. Создайте также Polynomial2 с контрактом ниже для проверки пользовательского типа.\n\n'+POLY,[case('Скалярные типы','int a=2,b=9; swap_values(a,b); CHECK(a==9 && b==2); double x=1.5,y=9.5; swap_values(x,y); CHECK(x==9.5 && y==1.5);'),case('Самоперестановка','int a=7; swap_values(a,a); CHECK(a==7);','boundary'),case('Пользовательский тип','Polynomial2 a(1,2,3),b(4,5,6); swap_values(a,b); CHECK(a==Polynomial2(4,5,6) && b==Polynomial2(1,2,3));','types')]+PCASES,tags=['References','Template deduction'])
code(3,'C','A4 · minimum_of_three<T>','Напишите template<class T> T minimum_of_three(T a,T b,T c). Используйте только < и копирование; верните минимальное значение.',MINCASES,tags=['Template deduction'])
code(3,'C','A5 · index_of_min<T>','Напишите std::size_t index_of_min(const T* array,std::size_t size). Пустой массив или nullptr → invalid_argument. При нескольких минимумах верните первый индекс. Используйте <.',IDXCASES,tags=['Template deduction','Exception safety'])
STRMAX=[case('Содержимое вместо адресов','char storage[][8]={"z","aa","ba"}; const char* a=storage[0]; const char* b=storage[1]; CHECK(maximum(a,b)==a); CHECK(maximum(b,a)==a);'),case('Равные и пустые строки','const char a[]="same",b[]="same"; CHECK(maximum(static_cast<const char*>(a),static_cast<const char*>(b))==a); CHECK(std::strcmp(maximum("","x"),"x")==0);','boundary'),case('nullptr','expect_throw<std::invalid_argument>([]{maximum(static_cast<const char*>(nullptr),"x");}); expect_throw<std::invalid_argument>([]{maximum("x",static_cast<const char*>(nullptr));});','negative')]
code(3,'C','B1 · String Overload','Реализуйте maximum(T,T) и отдельную обычную перегрузку maximum(const char*,const char*). Строки сравниваются через strcmp; равенство возвращает первый аргумент, nullptr → invalid_argument. Разберите отличие перегрузки от специализации в notes.md.',MAXCASES+STRMAX,level='B',tags=['Specialization'])
code(3,'C','B2 · String Specialization','Реализуйте maximum(T,T) и полную специализацию для const char*. Сравнение через strcmp, при равенстве первый указатель, nullptr → invalid_argument. Явный вызов maximum<const char*> тоже обязан использовать сравнение содержимого.',MAXCASES+STRMAX+[case('Явная специализация','const char a[]="z",b[]="aa"; CHECK(maximum<const char*>(a,b)==a); expect_throw<std::invalid_argument>([]{maximum<const char*>(nullptr,"");});')],level='B',tags=['Specialization'])
GENERIC='''Напишите три шаблона над обычными массивами: find_first(const T*,size_t,Predicate) -> size_t (индекс первого совпадения, при отсутствии — size); count_if(const T*,size_t,Predicate) -> size_t; swap_at(T*,size_t,size_t i,size_t j) -> void. Для первых двух nullptr допустим лишь при size=0. swap_at: nullptr → invalid_argument, любой индекс>=size → out_of_range, проверка предшествует изменению. Самоперестановка разрешена. Не используйте готовые алгоритмы STL. Сигнатуры оформите самостоятельно в соответствии с этими типами результатов.'''
GCASES=[case('Поиск и подсчёт','int a[]={-1,2,3,4}; auto even=[](int x){return x%2==0;}; CHECK(find_first(a,4,even)==1 && count_if(a,4,even)==2); CHECK(find_first(a,4,[](int x){return x>9;})==4);'),case('Пустые диапазоны','CHECK(find_first<int>(nullptr,0,[](int){return true;})==0); CHECK(count_if<int>(nullptr,0,[](int){return true;})==0);','boundary'),case('Перестановка','int a[]={1,2,3}; swap_at(a,3,0,2); CHECK(a[0]==3 && a[2]==1); swap_at(a,3,1,1); CHECK(a[1]==2);'),case('Ошибки сохраняют данные','int a[]={1,2}; expect_throw<std::out_of_range>([&]{swap_at(a,2,0,2);}); CHECK(a[0]==1 && a[1]==2); expect_throw<std::invalid_argument>([]{swap_at<int>(nullptr,1,0,0);}); expect_throw<std::invalid_argument>([]{count_if<int>(nullptr,1,[](int){return true;});});','negative'),case('std::string','std::string a[]={"x","long","hi"}; CHECK(find_first(a,3,[](const std::string& s){return s.size()>2;})==1);','types')]
code(3,'C','B3 · Generic Algorithms',GENERIC,GCASES,level='B',tags=['Template deduction','Exception safety'])
code(3,'C','C · Generic Utilities Challenge',GENERIC+'\n\nДополните набор maximum(T,T), minimum_of_three(T,T,T), index_of_min(const T*,size_t) с контрактами A2/A4/A5, повторёнными здесь: сравнение только <; пустой index_of_min или nullptr → invalid_argument, при равных минимумах первый индекс. Добавьте Polynomial2 по контракту ниже. Используйте Polynomial2 в find_first/count_if/swap_at по коэффициентам, не вводя искусственный порядок многочленов.\n\n'+POLY,GCASES+MAXCASES+MINCASES+IDXCASES+PCASES+[case('Алгоритмы над многочленами','Polynomial2 a[]={Polynomial2(1,0,0),Polynomial2(0,2,1)}; CHECK(find_first(a,2,[](const Polynomial2& p){return p[2]==0;})==1); swap_at(a,2,0,1); CHECK(a[0](2)==5);','types')],level='C',minutes=65,tags=['Template deduction','Проектирование'])

BOX='''Создайте template<class T> class Box с explicit-конструктором из const T&, const T& get() const и void set(const T&). Храните значение T непосредственно; определите методы вне класса.'''
code(4,'C','A1 · Box<T>',BOX,[case('Разные типы','Box<int> a(3); a.set(7); CHECK(a.get()==7); const Box<double> b(2.5); CHECK(b.get()==2.5);'),case('Строки и копии','Box<std::string> a("a"); auto b=a; b.set("b"); CHECK(a.get()=="a" && b.get()=="b");'),case('Ссылочный результат','const Box<int> a(4); CHECK(&a.get()==&a.get());')],checks='static_assert(std::is_same_v<decltype(std::declval<const Box<int>&>().get()),const int&>);',staticChecks=['external_methods'],tags=['Шаблоны классов'])
BUFFER='''Создайте template<class T,int Size=256> class FixedBuffer. Size должен быть положительным (static_assert). Храните собственный массив, элементы value-initialized. capacity() const -> std::size_t возвращает Size. Две версии [] возвращают T& / const T&, индекс>=Size → out_of_range. Не используйте STL-контейнеры.'''
code(4,'C','A2 · FixedBuffer<T, Size>',BUFFER,[case('Вместимость и начальные значения','FixedBuffer<int,3> a; CHECK(a.capacity()==3 && a[0]==0 && a[2]==0); CHECK(FixedBuffer<double>().capacity()==256);'),case('Ссылки и const','FixedBuffer<int,2> a; a[1]=8; const auto& b=a; CHECK(b[1]==8);'),case('Границы','FixedBuffer<int,1> a; const auto& b=a; expect_throw<std::out_of_range>([&]{(void)a[1];}); expect_throw<std::out_of_range>([&]{(void)b[1];});','negative'),case('Пользовательский тип','FixedBuffer<std::string,2> a; a[0]="ok"; auto b=a; b[0]="other"; CHECK(a[0]=="ok");','types')],staticChecks=['no_containers'],tags=['Шаблоны классов','const correctness'])
STACK='''Интерфейс стека: bool Push(const T&), bool Pop(T&), bool Get(T&) const, std::size_t Count() const, bool Empty() const, bool Full() const. Pop/Get пустого стека возвращают false, не меняя выходной аргумент; Get не удаляет. Push полного стека возвращает false без изменений. LIFO. Исключения T передаются вызывающему коду. Если копирование T бросает, сохраняются состояние и число элементов (сильная гарантия для Push/Pop/Get; выходной аргумент может быть изменён бросающим присваиванием самого T).'''
FIXED='''Реализуйте template<class T,int Size=256> class TFixedStack на собственном массиве фиксированной вместимости, Size>0 (static_assert). Элементы T должны быть default-constructible, копируемы и присваиваемы. Не менее трёх методов определите вне класса. '''+STACK
def stack_cases(name):
 return [case('Пустое состояние',f'{name} s; int v=91; CHECK(s.Empty() && s.Count()==0 && !s.Get(v) && !s.Pop(v) && v==91);','boundary'),case('LIFO и Get',f'{name} s; CHECK(s.Push(4)); CHECK(s.Push(7)); const auto& c=s; int v=0; CHECK(c.Get(v) && v==7 && s.Count()==2); CHECK(s.Pop(v) && v==7); CHECK(s.Pop(v) && v==4); CHECK(s.Empty());'),case('Повторное использование',f'{name} s; int out=0; for(int i=0;i<20;++i){{CHECK(s.Push(i)); CHECK(s.Pop(out) && out==i);}} CHECK(s.Count()==0);')]
FCASES=stack_cases('TFixedStack<int,3>')+[case('Полный стек','TFixedStack<int,2> s; CHECK(s.Push(1) && s.Push(2) && s.Full()); CHECK(!s.Push(3) && s.Count()==2); int out=0; CHECK(s.Pop(out) && out==2 && !s.Full());','boundary'),case('Копирование и тип string','TFixedStack<std::string,3> a; a.Push("a"); auto b=a; b.Push("b"); std::string out; CHECK(a.Get(out) && out=="a"); CHECK(b.Pop(out) && out=="b");','types'),case('Исключение при Push','TFixedStack<Tracked,3> s; Tracked v(7); Tracked::copies_before_throw=0; bool caught=false; try{s.Push(v);}catch(const std::runtime_error&){caught=true;} Tracked::copies_before_throw=-1; CHECK(caught && s.Count()==0);','exception')]
code(4,'C','A3 · TFixedStack<T, Size>',FIXED,FCASES,level='A',staticChecks=['no_containers','three_external_methods'],tags=['Шаблоны классов','Exception safety'])
ABSTRACT='''Реализуйте template<class T> class AbstractStack с чисто виртуальными методами следующего контракта и виртуальным деструктором. Для проверки создайте template<class T> class SingleStack : public AbstractStack<T> вместимостью 1, использующий override. '''+STACK
code(4,'C','B1 · AbstractStack<T>',ABSTRACT,[case('Абстрактность и виртуальный деструктор','CHECK(std::is_abstract_v<AbstractStack<int>>); CHECK(std::has_virtual_destructor_v<AbstractStack<int>>);'),case('Виртуальные вызовы','SingleStack<int> s; AbstractStack<int>& b=s; CHECK(b.Empty()); CHECK(b.Push(7) && b.Full()); CHECK(!b.Push(8)); int out=0; CHECK(b.Get(out) && out==7); CHECK(b.Pop(out) && out==7 && b.Empty());'),case('Удаление через базу','AbstractStack<std::string>* s=new SingleStack<std::string>(); s->Push("owned"); std::string out; CHECK(s->Pop(out) && out=="owned"); delete s;','memory')],level='B',memory=True,tags=['Наследование'])
DYNAMIC='''Реализуйте template<class T> class DynamicStack как односвязный список с вложенным узлом и владением через new/delete. Full() всегда false. Реализуйте глубокое копирование с сохранением порядка, копирующее присваивание и деструктор. Не используйте STL-контейнеры. '''+STACK
DCASES=stack_cases('DynamicStack<int>')+[case('Глубокое копирование и порядок','DynamicStack<int> a; a.Push(1); a.Push(2); DynamicStack<int> b(a); int out=0; CHECK(b.Pop(out) && out==2); CHECK(a.Count()==2); DynamicStack<int> c; c=b; c=c; CHECK(c.Pop(out) && out==1);'),case('Жизнь пользовательских объектов','const int before=Tracked::alive; {DynamicStack<Tracked> s; Tracked v(4); s.Push(v); s.Push(v); DynamicStack<Tracked> copy(s); CHECK(copy.Count()==2);} CHECK(Tracked::alive==before);','memory'),case('Исключение при вставке','DynamicStack<Tracked> s; Tracked v(4); Tracked::copies_before_throw=0; bool caught=false; try{s.Push(v);}catch(const std::runtime_error&){caught=true;} Tracked::copies_before_throw=-1; CHECK(caught && s.Count()==0);','exception'),case('Неудачное копирование цепочки','DynamicStack<Tracked> s; Tracked a(1),b(2); s.Push(a); s.Push(b); const int live=Tracked::alive; Tracked::copies_before_throw=1; bool caught=false; try{DynamicStack<Tracked> copy(s);}catch(const std::runtime_error&){caught=true;} Tracked::copies_before_throw=-1; CHECK(caught && Tracked::alive==live && s.Count()==2);','exception')]
code(4,'C','B2 · DynamicStack<T>',DYNAMIC,DCASES,memory=True,level='B',staticChecks=['no_containers'],tags=['Dynamic memory','Copy constructor'])
code(4,'C','B3 · Специализация char*','Реализуйте первичный template<class T> class TextStack (можно только объявление) и полную специализацию TextStack<char*>. Методы: bool Push(const char*), bool Pop(), const char* Get() const, size_t Count() const, bool Empty() const. Push копирует строку в собственный new[]-буфер; nullptr → invalid_argument. Get пустого → out_of_range; указатель Get заимствован до изменения/уничтожения стека. Pop удаляет строку и возвращает false на пустом. Реализуйте глубокое копирование стека, присваивание и освобождение всех узлов/строк. Внутри — собственный связный список.',[
case('Глубокая копия входного буфера','TextStack<char*> s; char a[]="hello"; CHECK(s.Push(a)); a[0]=char(88); CHECK(std::strcmp(s.Get(),"hello")==0);'),
case('LIFO и копия стека','TextStack<char*> a; a.Push("one"); a.Push("two"); auto b=a; CHECK(b.Pop()); CHECK(std::strcmp(b.Get(),"one")==0 && std::strcmp(a.Get(),"two")==0);'),
case('Пустой стек и nullptr','TextStack<char*> s; CHECK(s.Empty() && s.Count()==0 && !s.Pop()); expect_throw<std::out_of_range>([&]{s.Get();}); expect_throw<std::invalid_argument>([&]{s.Push(nullptr);}); CHECK(s.Count()==0);','negative'),
case('Присваивание и самоприсваивание','TextStack<char*> a,b; a.Push("alive"); b=a; a.Pop(); b=b; CHECK(std::strcmp(b.Get(),"alive")==0);'),
case('Разрушение и пустая строка','for(int i=0;i<40;++i){TextStack<char*> s; s.Push(""); CHECK(s.Get()[0]==0); s.Push("owned");}','memory')],memory=True,level='B',staticChecks=['no_containers'],tags=['Specialization','Dynamic memory'])
SHAPE='''Создайте абстрактную Shape с virtual double area() const и виртуальным деструктором. Rectangle(double width,double height), Circle(double radius) наследуют Shape, отрицательные размеры → invalid_argument, ноль допустим. Площадь окружности использует pi=3.141592653589793. Напишите Rectangle* as_rectangle(Shape*), Rectangle& require_rectangle(Shape&), bool is_exact_circle(const Shape&) (typeid), Shape* upcast(Rectangle*) (static_cast). Для неудачного cast указателя → nullptr, ссылки → bad_cast. Не сравнивайте строки type_info::name().'''
SHCASES=[case('Виртуальные площади','Rectangle r(3,4); Circle c(2); const Shape& a=r; const Shape& b=c; CHECK(a.area()==12); CHECK(std::abs(b.area()-12.566370614359172)<1e-10);'),case('Успешные преобразования','Rectangle r(2,4); Shape* b=upcast(&r); CHECK(as_rectangle(b)==&r && &require_rectangle(*b)==&r);'),case('Неудачные преобразования','Circle c(1); CHECK(as_rectangle(&c)==nullptr && as_rectangle(nullptr)==nullptr); expect_throw<std::bad_cast>([&]{require_rectangle(c);});','negative'),case('Точный динамический тип','Circle c(2); Rectangle r(2,2); struct Sub:Circle{Sub():Circle(1){}}; Sub sub; CHECK(is_exact_circle(c) && !is_exact_circle(r) && !is_exact_circle(sub));'),case('Нулевые и отрицательные размеры','CHECK(Circle(0).area()==0 && Rectangle(0,2).area()==0); expect_throw<std::invalid_argument>([]{Circle c(-1);}); expect_throw<std::invalid_argument>([]{Rectangle r(1,-2);});','boundary')]
code(4,'C','B4 · RTTI Laboratory',SHAPE,SHCASES,level='B',tags=['RTTI','Наследование'])
code(4,'C','C · Stack Architecture Challenge','Реализуйте AbstractStack<T> с виртуальными методами стека и деструктором. Обе реализации ниже должны публично наследовать интерфейс и использовать override.\n\n'+FIXED+'\n\n'+DYNAMIC+'''\n\nДобавьте template<class T> bool round_trip(AbstractStack<T>& stack,const T& a,const T& b,T& first,T& second): предусловие — стек пустой с местом хотя бы для двух элементов. Push(a), Push(b), затем Pop(first), Pop(second); true только при успехе всех операций. Нельзя определять конкретный тип через RTTI. В notes.md объясните полиморфное уничтожение.''',FCASES+DCASES+[case('Общий алгоритм','TFixedStack<int,4> a; DynamicStack<int> b; int first=0,second=0; CHECK(round_trip<int>(a,4,9,first,second) && first==9 && second==4); CHECK(round_trip<int>(b,4,9,first,second) && first==9 && second==4);'),case('Уничтожение через интерфейс','AbstractStack<Tracked>* s=new DynamicStack<Tracked>(); const int base=Tracked::alive; {Tracked t(3); s->Push(t);} delete s; CHECK(Tracked::alive==base);','memory')],level='C',minutes=80,memory=True,staticChecks=['no_containers','no_rtti','three_external_methods'],tags=['Наследование','Dynamic memory','Проектирование'])

SEQUENCE='''Создайте с нуля template<class T> class TSequence. Хранение — собственный динамический массив new T[], без std::vector/deque/list/array/string и других контейнеров для хранения, без RTTI-выбора поведения. Тип T: конструктор по умолчанию, копирование и присваивание; == нужен только при сравнении, << только при выводе. Нельзя требовать <. Обязательны: пустой конструктор; explicit-конструктор TSequence(std::size_t count) с value-initialized элементами; правило трёх; size() const -> size_t, empty() const -> bool; две версии [](size_t) -> T& / const T&; void push_back(const T&); void insert(size_t position,const T&); void erase(size_t position); ==, !=; вывод [a,b,c] (пустой: []). insert принимает position<=size, []/erase требуют position<size, иначе out_of_range. Сначала проверяйте границы, затем изменяйте объект. Поддержите самостоятельное владение, независимость копий, цепочку присваиваний, самоприсваивание, рост и алиасинг push_back(s[0])/insert(0,s[1]). Все изменяющие операции и копирование обеспечивают сильную гарантию при исключении: ресурсы не теряются, старое состояние сохраняется. Проверяйте переполнение количества и байтов до выделения, бросайте length_error. Не перехватывайте и не скрывайте bad_alloc/ошибки T. Требования к T позволяют использовать new T[capacity]. Проверки используют int, double, std::string как значение элемента (допустимо), и Tracked — пользовательский тип с копированием, ==, <<, без <, иногда бросающий из копирования. Реализуйте заголовок самостоятельно; стартового решения нет.'''
SEQCASES=[
case('Пустой контейнер','const TSequence<int> s; CHECK(s.size()==0 && s.empty()); std::ostringstream o; o<<s; CHECK(o.str()=="[]");','boundary'),
case('Конструктор размера','const TSequence<int> s(3); CHECK(s.size()==3 && s[0]==0 && s[2]==0); const TSequence<double> d(2); CHECK(d[1]==0.0);'),
case('Рост','TSequence<int> s; for(int i=0;i<100;++i)s.push_back(i*2); CHECK(s.size()==100); for(int i=0;i<100;++i)CHECK(s[static_cast<std::size_t>(i)]==i*2);'),
case('Вставки в начало, середину, конец','TSequence<int> s; s.push_back(2); s.push_back(4); s.insert(0,1); s.insert(2,3); s.insert(s.size(),5); CHECK(s.size()==5); for(std::size_t i=0;i<5;++i)CHECK(s[i]==static_cast<int>(i)+1);'),
case('Удаления','TSequence<int> s; for(int i=1;i<=4;++i)s.push_back(i); s.erase(0); s.erase(s.size()-1); CHECK(s.size()==2 && s[0]==2 && s[1]==3); s.erase(1); s.erase(0); CHECK(s.empty());'),
case('Независимость копий','TSequence<int> a; a.push_back(1); a.push_back(2); TSequence<int> b(a); b[0]=9; CHECK(a[0]==1 && b[0]==9);'),
case('Цепочки и самоприсваивание','TSequence<int> a,b,c; c.push_back(7); CHECK(&(a=b=c)==&a); b[0]=3; CHECK(a[0]==7 && c[0]==7); a=a; CHECK(a.size()==1 && a[0]==7);'),
case('Копия пустого объекта','TSequence<int> a; TSequence<int> b(a); b.push_back(8); CHECK(a.empty() && b.size()==1); TSequence<int> c(4); c=a; CHECK(c.empty());','boundary'),
case('Исключения диапазона','TSequence<int> s; expect_throw<std::out_of_range>([&]{(void)s[0];}); expect_throw<std::out_of_range>([&]{s.erase(0);}); expect_throw<std::out_of_range>([&]{s.insert(1,3);}); s.push_back(7); const auto& c=s; expect_throw<std::out_of_range>([&]{(void)c[1];}); expect_throw<std::out_of_range>([&]{s.erase(1);}); CHECK(s.size()==1 && s[0]==7);','negative'),
case('Алиасинг при росте','TSequence<std::string> s; s.push_back("first"); for(int i=0;i<32;++i)s.push_back(s[0]); CHECK(s.size()==33); for(std::size_t i=0;i<s.size();++i)CHECK(s[i]=="first");'),
case('Алиасинг при вставке','TSequence<std::string> s; s.push_back("a"); s.push_back("b"); s.insert(0,s[1]); CHECK(s.size()==3 && s[0]=="b" && s[1]=="a" && s[2]=="b");'),
case('Тип double и const','TSequence<double> s; s.push_back(2.5); s.push_back(-1.25); const auto& c=s; CHECK(c[0]+c[1]==1.25);','types'),
case('Пользовательский тип и уничтожение','const int before=Tracked::alive; {TSequence<Tracked> s; Tracked t(4); s.push_back(t); s.push_back(t); TSequence<Tracked> b(s); b.erase(0); CHECK(b[0].value==4 && s.size()==2);} CHECK(Tracked::alive==before);','memory'),
case('Сравнения и вывод','TSequence<int> a; a.push_back(1); a.push_back(2); auto b=a; CHECK(a==b && !(a!=b)); b[1]=3; CHECK(a!=b); std::ostringstream o; CHECK(&(o<<a)==&o); CHECK(o.str()=="[1,2]");'),
case('Исключение при Push и сохранение','TSequence<Tracked> s; Tracked a(1),b(2); s.push_back(a); const int alive=Tracked::alive; Tracked::copies_before_throw=0; bool caught=false; try{s.push_back(b);}catch(const std::runtime_error&){caught=true;} Tracked::copies_before_throw=-1; CHECK(caught && s.size()==1 && s[0].value==1 && Tracked::alive==alive);','exception'),
case('Неудачное копирование','TSequence<Tracked> s; Tracked t(4); s.push_back(t); s.push_back(t); const int alive=Tracked::alive; Tracked::copies_before_throw=1; bool caught=false; try{TSequence<Tracked> copy(s);}catch(const std::runtime_error&){caught=true;} Tracked::copies_before_throw=-1; CHECK(caught && Tracked::alive==alive && s.size()==2);','exception'),
case('Отказ присваивания','TSequence<Tracked> a,b; a.push_back(Tracked(1)); b.push_back(Tracked(9)); b.push_back(Tracked(8)); const int alive=Tracked::alive; Tracked::copies_before_throw=1; bool caught=false; try{a=b;}catch(const std::runtime_error&){caught=true;} Tracked::copies_before_throw=-1; CHECK(caught && a.size()==1 && a[0].value==1 && Tracked::alive==alive);','exception'),
case('Исключение при insert','TSequence<Tracked> s; s.push_back(Tracked(1)); s.push_back(Tracked(2)); Tracked v(3); const int alive=Tracked::alive; Tracked::copies_before_throw=1; bool caught=false; try{s.insert(0,v);}catch(const std::runtime_error&){caught=true;} Tracked::copies_before_throw=-1; CHECK(caught && s.size()==2 && s[0].value==1 && s[1].value==2 && Tracked::alive==alive);','exception'),
case('Исключение при erase','TSequence<Tracked> s; s.push_back(Tracked(1)); s.push_back(Tracked(2)); s.push_back(Tracked(3)); const int alive=Tracked::alive; Tracked::copies_before_throw=0; bool caught=false; try{s.erase(0);}catch(const std::runtime_error&){caught=true;} Tracked::copies_before_throw=-1; if(caught){CHECK(s.size()==3 && s[0].value==1 && s[2].value==3 && Tracked::alive==alive);}else{CHECK(s.size()==2 && s[0].value==2 && s[1].value==3);}','exception'),
case('Переполнение размера','expect_throw<std::length_error>([]{TSequence<double> s(std::numeric_limits<std::size_t>::max());});','negative'),
]
SEQTYPE='static_assert(std::is_same_v<decltype(std::declval<TSequence<int>&>()[0]),int&>); static_assert(std::is_same_v<decltype(std::declval<const TSequence<int>&>()[0]),const int&>);'
code(5,'C','A · TSequence — основной экзамен',SEQUENCE,SEQCASES,checks=SEQTYPE,memory=True,level='A',minutes=120,staticChecks=['no_containers','no_rtti'],tags=['Dynamic memory','Exception safety','Шаблоны классов','Assignment operator'])
code(5,'C','B · Универсальный клиент контейнера',SEQUENCE+'\n\nДобавьте функцию-шаблон TSequence<T> reversed_copy(const TSequence<T>&): независимая обратная копия; оригинал сохраняется. Запрещено обращаться к приватному хранению. Не требуйте у T сравнений порядка. Это обязательная интеграционная часть экзамена.',SEQCASES+[case('Клиент и независимость','TSequence<int> s; s.push_back(1); s.push_back(2); s.push_back(3); auto r=reversed_copy(s); CHECK(r.size()==3 && r[0]==3 && r[2]==1 && s[0]==1); r[0]=9; CHECK(s[2]==3);'),case('Пустой и пользовательский тип','const TSequence<int> e; CHECK(reversed_copy(e).empty()); TSequence<Tracked> s; s.push_back(Tracked(7)); CHECK(reversed_copy(s)[0].value==7);','types')],memory=True,level='B',minutes=30,staticChecks=['no_containers','no_rtti'],tags=['Template deduction','Проектирование'])
code(5,'C','C · Проверка исключений и интеграции',SEQUENCE+'\n\nРеализуйте также CMyString по следующему контракту и проверьте контейнер с этим типом.\n\n'+STRING+'\n\nДобавьте потоковый вывод CMyString (само содержимое без кавычек). Это обязательная комплексная проверка владения на двух уровнях; в notes.md перечислите инварианты и последствия отказа на каждой фазе копирования.',SEQCASES+SCASES+[case('Контейнер собственных строк','TSequence<CMyString> s; s.push_back(CMyString("one")); s.push_back(CMyString("two")); auto copy=s; copy[0][0]=char(88); CHECK(s[0]==CMyString("one")); s.insert(0,s[1]); CHECK(s[0]==CMyString("two") && s.size()==3); std::ostringstream o; o<<s; CHECK(o.str()=="[two,one,two]");','types')],memory=True,level='C',minutes=60,staticChecks=['no_containers','no_rtti'],tags=['Dynamic memory','Exception safety','Проектирование'])
code(5,'C','C+ · Move-семантика (расширение)',SEQUENCE+'\n\nДополнительная сложность за рамками основной программы: добавьте noexcept move-конструктор и move-присваивание. Перемещённый объект должен быть пустым, безопасным для повторного push_back и уничтожения; самоперемещение допустимо. Не входит в обязательный процент.',SEQCASES+[case('Перемещение и повторное использование','TSequence<int> a; a.push_back(7); TSequence<int> b(std::move(a)); CHECK(b[0]==7 && a.empty()); a.push_back(9); b=std::move(a); CHECK(b[0]==9 && a.empty()); b=std::move(b); CHECK(b.size()<=1);')],checks=SEQTYPE+' static_assert(std::is_nothrow_move_constructible_v<TSequence<int>> && std::is_nothrow_move_assignable_v<TSequence<int>>);',memory=True,level='C',minutes=35,required=False,staticChecks=['no_containers','no_rtti'],tags=['Dynamic memory'])
